<?php /** @var array<string,mixed> $attributes */ declare( strict_types=1 );if( !defined( 'ABSPATH' ) ){exit;}$nextsaas_questions=nextsaas_items( $attributes, 'questions' );?>
<section <?php echo nextsaas_section_attrs( 'pricing-pricing-questions', $attributes, array( 'section' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?>><div class="container"><div class="grid-1-2"><div><p class="eyebrow" data-nextsaas-rich="eyebrow"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'eyebrow' ) ); ?></p><h2 data-nextsaas-rich="heading"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'heading' ) ); ?></h2><a class="text-link" href="<?php echo esc_url( nextsaas_resolve_url( nextsaas_attr( $attributes, 'ctaUrl' ) ) ); ?>" data-nextsaas-rich="ctaLabel"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'ctaLabel' ) ); ?> <?php echo nextsaas_icon( 'arrow-up-right' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?></a></div><div class="faq"><?php foreach( $nextsaas_questions as $nextsaas_i=>$nextsaas_question ): ?><details data-category="<?php echo esc_attr( (string)( $nextsaas_question['category']??'' ) ); ?>"><summary><span data-nextsaas-rich="questions.<?php echo esc_attr( (string)$nextsaas_i ); ?>.question"><?php echo nextsaas_rich( (string)( $nextsaas_question['question']??'' ) ); ?></span><?php echo nextsaas_icon( 'plus' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?></summary><p data-nextsaas-rich="questions.<?php echo esc_attr( (string)$nextsaas_i ); ?>.answer"><?php echo nextsaas_rich( (string)( $nextsaas_question['answer']??'' ) ); ?></p></details><?php endforeach; ?></div></div></div></section>
